  var norm = function (s) { return String(s).replace(/[\s\u00a0]+/g, " ").trim(); };
  var map = new Map();
  P.forEach(function (p) { map.set(norm(p[0]), p[1]); });
  var TITLE = { en: "Ishkhan – Product Designer", ru: "Ишхан – продуктовый дизайнер" };
  var ATTRS = ["placeholder", "alt", "aria-label", "title"];
  var lang = "en";
  try { lang = localStorage.getItem("site-lang") === "ru" ? "ru" : "en"; } catch (e) {}

  function tr(s) {
    var m = /^(\s*)([\s\S]*?)(\s*)$/.exec(s);
    var v = map.get(norm(m[2]));
    return v == null ? null : m[1] + v + m[3];
  }
  function skip(el) { return !el || el.closest && el.closest("script,style,[data-no-i18n]"); }
  var MAXFLIP = 6;
  function guard(o) {
    var now = Date.now();
    if (!o.__i18nT || now - o.__i18nT > 2000) { o.__i18nT = now; o.__i18nN = 0; }
    return ++o.__i18nN <= MAXFLIP;
  }
  function doText(n) {
    if (skip(n.parentElement)) return;
    var cur = n.nodeValue;
    if (n.__ru === undefined || (cur !== n.__ru && cur !== n.__en)) { n.__en = cur; n.__ru = tr(cur); }
    else if (cur === n.__en && n.__ru == null) { n.__ru = tr(cur); }
    if (n.__ru == null) return;
    var want = lang === "ru" ? n.__ru : n.__en;
    if (cur !== want && guard(n)) n.nodeValue = want;
  }
  function doAttrs(el) {
    if (skip(el) || el.tagName.indexOf("-") > 0) return;
    for (var i = 0; i < ATTRS.length; i++) {
      var a = ATTRS[i]; if (!el.hasAttribute(a)) continue;
      var cur = el.getAttribute(a);
      el.__i18n = el.__i18n || {};
      var r = el.__i18n[a];
      if (!r || (cur !== r.ru && cur !== r.en)) { r = el.__i18n[a] = { en: cur, ru: tr(cur) }; }
      if (r.ru == null) continue;
      var want = lang === "ru" ? r.ru : r.en;
      if (cur !== want && guard(el)) el.setAttribute(a, want);
    }
  }
  function walk(root) {
    if (!root || !root.isConnected) return;
    if (root.nodeType === 3) return doText(root);
    if (root.nodeType !== 1) return;
    doAttrs(root);
    var w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
    var n;
    while ((n = w.nextNode())) { if (n.nodeType === 3) doText(n); else doAttrs(n); }
  }
  var OPTS = { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATTRS };
  var queue = new Set(), scheduled = false, full = false;
  function flush() {
    scheduled = false;
    obs.disconnect();
    try {
      if (full) { full = false; queue.clear(); document.documentElement.lang = lang; document.title = TITLE[lang]; walk(document.body); }
      else { var q = Array.from(queue); queue.clear(); for (var i = 0; i < q.length; i++) walk(q[i]); }
    } finally { obs.observe(document.body, OPTS); }
  }
  function schedule() { if (!scheduled) { scheduled = true; setTimeout(flush, 0); } }
  function apply() { full = true; schedule(); }
  var obs = new MutationObserver(function (list) {
    if (full) return schedule();
    for (var i = 0; i < list.length; i++) {
      var m = list[i];
      if (m.type === "childList") { for (var j = 0; j < m.addedNodes.length; j++) queue.add(m.addedNodes[j]); }
      else queue.add(m.target);
    }
    if (queue.size > 400) { queue.clear(); full = true; }
    schedule();
  });
  function start() { obs.observe(document.body, OPTS); apply(); }
  if (document.body) start(); else document.addEventListener("DOMContentLoaded", start);
  window.__i18n = {
    get lang() { return lang; },
    set: function (l) {
      lang = l === "ru" ? "ru" : "en";
      try { localStorage.setItem("site-lang", lang); } catch (e) {}
      document.documentElement.lang = lang;
      apply();
      window.dispatchEvent(new CustomEvent("langchange", { detail: lang }));
    }
  };
